Port 8080 is open — let me check whether that's actually the KV service before drawing conclusions.

```python
import urllib.request, json

def get(path):
    url = f"http://127.0.0.1:8080{path}"
    try:
        with urllib.request.urlopen(url, timeout=3) as r:
            return r.status, r.read(1000).decode('utf-8', 'replace')
    except Exception as ex:
        return None, f"<error: {type(ex).__name__}: {ex}>"

for p in ('/', '/status', '/cluster', '/health', '/leader', '/v1/status', '/metrics'):
    code, body = get(p)
    print(f"--- GET {p} -> {code}")
    if body:
        print(body[:400].strip())
    print()
